<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ArrowLeft, Save } from 'lucide-vue-next'
import { useRoute, useRouter } from 'vue-router'
import { loadCheckoutData, saveAddress, updateAddress } from '../services/orderService'
import { useSessionStore } from '../stores/session'
const router = useRouter(); const route = useRoute(); const session = useSessionStore(); const draft = ref(null); const zones = ref([]); const saving = ref(false); const error = ref(''); const form = reactive({ alias: 'Casa', detalle: '', referencia: '', zona_id: '', latitud: null, longitud: null, localidad: '', ciudad: '', departamento: '', pais: '' })
async function load() { draft.value = JSON.parse(sessionStorage.getItem('pedidosya-address-draft') || 'null'); if (!draft.value) { router.replace({ name: 'checkout' }); return }; const data = await loadCheckoutData(session.user.id); zones.value = data.zones; Object.assign(form, { alias: draft.value.geocode?.alias || 'Casa', detalle: draft.value.geocode?.detalle || draft.value.geocode?.display || '', referencia: '', zona_id: zones.value[0]?.id || '', latitud: draft.value.lat, longitud: draft.value.lon, localidad: draft.value.geocode?.localidad || '', ciudad: draft.value.geocode?.ciudad || '', departamento: draft.value.geocode?.departamento || '', pais: draft.value.geocode?.pais || '' }); if (draft.value.id) { const existing = data.addresses.find((item) => item.id === draft.value.id); if (existing) Object.assign(form, existing) } }
async function save() { if (!form.detalle.trim() || !form.zona_id) { error.value = 'Completa la dirección y la zona de entrega.'; return }; saving.value = true; error.value = ''; try { const isRegistration = draft.value.from === 'register' || route.query.from === 'register'; const saved = draft.value.id ? await updateAddress(session.user.id, draft.value.id, form) : await saveAddress(session.user.id, form, { predeterminada: isRegistration }); sessionStorage.removeItem('pedidosya-address-draft'); if (isRegistration) { const redirect = typeof route.query.redirect === 'string' && route.query.redirect.startsWith('/') ? route.query.redirect : draft.value.redirect?.startsWith('/') ? draft.value.redirect : '/cliente'; router.replace(redirect) } else router.replace({ name: 'checkout', query: { address: saved.id } }) } catch (e) { error.value = e.message || 'No se pudo guardar la dirección.' } finally { saving.value = false } }
function cancel() { sessionStorage.removeItem('pedidosya-address-draft'); router.replace({ name: 'checkout' }) }
onMounted(load)
</script>
<template><main class="address-details-page"><header><button @click="router.back"><ArrowLeft :size="22" /></button><h1>Confirma tu dirección</h1><button class="address-header-cancel" @click="cancel">Cancelar</button></header><section class="address-details-content"><div class="address-location-summary"><strong>Ubicación seleccionada</strong><p>{{ form.detalle || 'Punto seleccionado en el mapa' }}</p><button @click="router.back">Cambiar ubicación</button></div><form @submit.prevent="save"><label>Alias<input v-model="form.alias" placeholder="Casa, Trabajo u Otro" /></label><label>Calle y número<input v-model="form.detalle" required /></label><label>Colonia o barrio<input v-model="form.localidad" placeholder="Opcional" /></label><label>Ciudad o municipio<input v-model="form.ciudad" placeholder="Opcional" /></label><label>Departamento<input v-model="form.departamento" placeholder="Opcional" /></label><label>Referencia para el repartidor<textarea v-model="form.referencia" rows="3" placeholder="Portón, edificio, punto de referencia…" /></label><label>Zona de entrega<select v-model="form.zona_id" required><option value="" disabled>Selecciona una zona</option><option v-for="zone in zones" :key="zone.id" :value="zone.id">{{ zone.nombre }}</option></select></label><p v-if="error" class="checkout-error">{{ error }}</p><button class="address-save-fixed" :disabled="saving"><Save :size="17" /> {{ saving ? 'Guardando…' : 'Guardar dirección' }}</button><button type="button" class="address-cancel-fixed" @click="cancel">Cancelar</button></form></section></main></template>
